from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.directions = deque([0, 1, 0, -1])

    def turn_right(self):
        self.directions.rotate(-1)

    def turn_left(self):
        self.directions.rotate(1)

    def walk_forward(self, n):
        for _ in range(n):
            self.x += self.directions[0]
            self.y += self.directions[1]

# Instantiate the robot
robot = Robot()

# Process the instructions
instructions = [
    ('walk', 3),
    ('walk', 4),
    ('walk', 2),
    ('walk', 4),
    ('walk', 2),
    ('turn', 'right'),
    ('walk', 1),
    ('walk', 2),
    ('turn', 'left'),
    ('turn', 'right')
]

for kind, n in instructions:
    if kind == 'walk':
        robot.walk_forward(n)
    elif kind == 'turn':
        if n == 'right':
            robot.turn_right()
        else:
            robot.turn_left()

print((robot.x, robot.y))
