from collections import deque

def parse_turns(turns):
    turns = ['L', 'L', 'L']
    for _ in range(3):
        turns.append(turns[0])
    return turns

def turn_right(turns):
    turns[0] = turns[2]
    turns[1] = turns[3]
    turns[2] = turns[1]
    turns[3] = turns[0]

def move(steps, direction):
    if direction == 'north':
        return 0, steps
    if direction == 'east':
        return steps, 0

def walk(steps, direction):
    return steps, direction

def robot_instructions(steps, directions):
    turns = deque(parse_turns(directions))
    x, y = 0, 0
    for step, direction in zip(steps, directions):
        x, y = move(step, direction)
        turns.rotate(-1)
    return x, y

