    'walk forward 2 steps',
    'walk forward 4 steps',
    'walk forward 1 step',
    'turn left',
    'turn right',
    'turn left',
    'walk forward 1 step',
    'walk forward 4 steps',
    'turn right',
    'walk forward 3 steps'
]

for instruction in instructions:
    robot.turn(instruction.split()[1])
    robot.walk(int(instruction.split()[0]))

print(robot.get_position())
