import math

def turn_right(current_direction):
    # Assuming the directions are 'north', 'east', 'south', 'west'
    # 'north' is (0, 1), 'east' is (1, 0), 'south' is (0, -1), 'west' is (-1, 0)
    return 'east' if current_direction == 'north' else 'south' if current_direction == 'east' else 'west' if current_direction == 'south' else 'north'

def turn_left(direction):
    return turn_right(turn_right(direction))

def walk_forward(steps, direction):
    dx, dy = 0, 0
    if direction == 'north':
        dx, dy = 0, 1
    elif direction == 'east':
        dx, dy = 1, 0
    elif direction == 'south':
        dx, dy = 0, -1
    elif direction == 'west':
        dx, dy = -1, 0
    return (dx * steps, dy * steps)

def simulate_robot_instructions():
    x, y = 0, 0
