from enum import Enum
from collections import namedtuple

class Direction(Enum):
    NORTH = 0
    EAST = 1
    SOUTH = 2
    WEST = 3

def turn_right(d):
    return (d + 1) % 4

def turn_left(d):
    return (d - 1) % 4

def walk_forward(d, n):
    if d == Direction.NORTH:
        return (0, n)
    elif d == Direction.EAST:
        return (n, 0)
    elif d == Direction.SOUTH:
        return (0, -n)
    elif d == Direction.WEST:
        return (-n, 0)

def turn_ahead(d):
    return (d + 1) % 4

def turn_back(d):
    return (d - 1) % 4

def solve():
    pos = (0, 0)
    d = Direction.NORTH
    for i in range(10):
        if i == 2 or i == 4 or i == 6 or i == 8:
            d = turn_ahead(d)
        elif i == 7:
            d = turn_back(d)
        elif i == 3 or i == 5 or i == 7:
            d = turn_right(d)
        elif i == 1 or i == 3 or i == 5:
            d = turn_left(d)
        else:
            d = turn_right(d)
        pos = walk_forward(d, 1)
        if i == 1 or i == 5:
            d = turn_right(d)

    return pos

print(solve())
