from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.directions = deque([0, 1, 0, -1])

    def turn(self, instruction):
        if instruction == 'left':
            self.directions.rotate(-1)
        elif instruction == 'right':
            self.directions.rotate(1)
        else:
            raise ValueError("Invalid instruction")

    def walk(self, distance):
        for _ in range(distance):
            if self.directions[0]:
                self.y += 1
            elif self.directions[1]:
                self.x += 1
            self.turn(self.directions[2])
            self.turn(self.directions[3])

    def final_position(self):
        return (self.x, self.y)

# Create a robot instance and execute the instructions
