        elif self.facing == 'east':
            self.facing = 'south'
        elif self.facing == 'south':
            self.facing = 'west'
        elif self.facing == 'west':
            self.facing = 'north'

    def walk(self, steps):
        direction = self.directions[self.facing]
        for _ in range(steps):
            self.x += direction[0]
            self.y += direction[1]

