from collections import deque

class Robot:
    def __init__(self, facing='n'):
        self.x = 0
        self.y = 0
        self.facing = facing

    def turn_right(self):
        if self.facing == 'n':
            self.facing = 'w'
        elif self.facing == 'w':
            self.facing = 's'
        elif self.facing == 's':
            self.facing = 'e'
        elif self.facing == 'e':
            self.facing = 'n'

    def turn_left(self):
        if self.facing == 'n':
            self.facing = 'e'
        elif self.facing == 'e':
            self.facing = 's'
        elif self.facing == 's':
            self.facing = 'w'
        elif self.facing == 'w':
            self.facing = 'n'

    def move(self):
        if self.facing == 'n':
            self.y += 1
        elif self.facing == 'w':
            self.x -= 1
        elif self.facing == 's':
            self.y -= 1
        elif self.facing == 'e':
            self.x += 1

    def turn_to(self, facing):
        if self.facing == 'n':
            if facing == 'w':
                self.turn_right()
            else:
                self.turn_right()
                self.turn_right()
        elif self.facing == 'w':
            if facing == 'n':
                self.turn_right()
            else:
                self.turn_right()
                self.turn_left()
        elif self.facing == 's':
            if facing == 'e':
                self.turn_left()
            else:
                self.turn_right()
                self.turn_right()
        elif self.facing == 'e':
            if facing == 'n':
                self.turn_left()
            else:
                self.turn_right()
                self.turn_right()

    def move_forward(self, forward):
        for _ in range(forward):
            self.turn_to('n')
            self.move()
            self.turn_to('w')
            self.move()
            self.turn_to('s')
            self.move()
            self.turn_to('e')
            self.move()

    def __str__(self):
        return f'({self.x}, {self.y})'

