class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.directions = deque([0, 1, 0, -1])

    def turn_right(self):
        self.directions.rotate(-1)

    def turn_left(self):
        self.directions.rotate(1)

    def walk(self, steps):
        self.x += steps * self.directions[0]
        self.y += steps * self.directions[1]

