        if instruction == 'walk forward':
            steps = int(instructions.pop())
            self.walk(steps)
        elif instruction == 'turn right':
            self.turn_right()
        elif instruction == 'turn left':
            self.turn_left()
        elif instruction == 'turn around':
            self.turn_left()
            self.turn_left()

    def get_position(self):
        return self.x, self.y

