def turn_right(current):
    # Define directions and their corresponding rotations
    directions = {
        'north': ('east', 'south', 'west'),
        'east': ('north', 'south', 'west'),
        'south': ('east', 'north', 'west'),
        'west': ('east', 'north', 'south')
    }
