def turn_left(current):
    # Define directions and their corresponding rotations
    directions = {
        'north': ('east', 'south', 'west'),
        'east': ('north', 'south', 'west'),
        'south': ('east', 'north', 'west'),
        'west': ('east', 'north', 'south')
    }
    return directions[current][0]

def walk(steps, direction):
    # Define directions and their corresponding offsets
    directions = {
        'north': (0, 1),
        'east': (1, 0),
        'south': (0, -1),
        'west': (-1, 0)
    }
    return directions[direction][0] * steps, directions[direction][1] * steps

def main():
