from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.directions = deque([0, 1, 0, -1])

    def turn(self, instruction):
        if instruction == 'left':
            self.directions.rotate(-1)
        elif instruction == 'right':
            self.directions.rotate(1)
        else:
            self.directions.rotate(-2)

    def walk(self, steps):
        for _ in range(steps):
            if steps % 2 == 0:
                self.y += self.directions[0]
                self.x += self.directions[1]
            else:
                self.y += self.directions[1]
                self.x += self.directions[0]

    def get_position(self):
        return (self.x, self.y)

