class Robot:
    def __init__(self):
        self.direction = 0  # 0: north, 1: east, 2: south, 3: west
        self.position = (0, 0)

    def turn_right(self):
        self.direction = (self.direction + 1) % 4

    def turn_left(self):
        self.direction = (self.direction - 1) % 4

    def move_forward(self, steps):
        if self.direction == 0:  # north
            self.position = (self.position[0], self.position[0] + steps)
        elif self.direction == 1:  # east
            self.position = (self.position[0] + steps, self.position[0])
        elif self.direction == 2:  # south
            self.position = (self.position[0], self.position[0] - steps)
        elif self.direction == 3:  # west
            self.position = (self.position[0] - steps, self.position[0])

    def run(self, instructions):
        for instruction in instructions:
            if instruction == 'turn_right':
                self.turn_right()
            elif instruction == 'turn_left':
                self.turn_left()
            elif instruction == 'walk_forward 2':
                self.move_forward(2)
            elif instruction == 'walk_forward 3':
                self.move_forward(3)

    def final_position(self):
        return self.position

