    # 0: north, 1: east, 2: south, 3: west
    global direction
    direction = (direction + 1) % 4

def turn_left():
    # Turn left. Since the robot is facing north, the directions are:
    # 0: north, 1: east, 2: south, 3: west
    global direction
    direction = (direction - 1) % 4

def walk_forward(steps):
    # Walk forward the specified number of steps. Since the robot is facing north, the directions are:
    # 0: north, 1: east, 2: south, 3: west
    global direction
    while steps > 0:
        if direction == 0:
            steps -= 1
            if steps == 0:
                break
        elif direction == 1:
            steps -= 1
            if steps == 0:
