class Robot:
    def __init__(self, position=(0, 0), facing=(0, 1)):
        self.position = position
        self.facing = facing

    def turn_left(self):
        self.facing = (-self.facing[1], self.facing[0])

    def walk(self, steps):
        self.position[0] += steps * self.facing[0]
        self.position[1] += steps * self.facing[1]

    def turn_right(self):
        self.facing = (self.facing[1], -self.facing[0])

    def walk_right(self, steps):
        self.position[0] += steps * self.facing[0]
        self.position[1] += steps * self.facing[1]

    def walk_forward(self, steps, facing_direction):
        if facing_direction == 'north':
            self.position[1] += steps
        elif facing_direction == 'east':
            self.position[0] += steps

    def move(self, instructions):
        for instruction in instructions:
            if instruction == 'turn left':
                self.turn_left()
            elif instruction == 'walk forward 1 step':
                self.walk(1)
            elif instruction == 'turn right':
                self.turn_right()
            elif instruction == 'walk forward 3 steps':
                self.walk(3)
            elif instruction == 'turn around':
                self.turn_right()
                self.turn_right()
            elif instruction == 'walk forward':
                self.walk_forward(1, self.facing)
            elif instruction == 'walk right':
                self.walk_forward(1, self.facing[1], self.facing[0])

