class Robot:
    def __init__(self, facing='n'):
        self.x = 0
        self.y = 0
        self.facing = facing

    def turn_right(self):
        if self.facing == 'n':
            self.facing = 'w'
        elif self.facing == 'w':
            self.facing = 's'
        elif self.facing == 's':
            self.facing = 'e'
        elif self.facing == 'e':
            self.facing = 'n'

    def turn_left(self):
        if self.facing == 'n':
            self.facing = 'e'
        elif self.facing == 'w':
            self.facing = 'n'
        elif self.facing == 's':
            self.facing = 'w'
        elif self.facing == 'e':
            self.facing = 's'

    def walk_forward(self, steps):
        if self.facing == 'n':
            self.y += steps
        elif self.facing == 'w':
            self.x -= steps
        elif self.facing == 's':
            self.y -= steps
        elif self.facing == 'e':
            self.x += steps

    def run_instructions(self, instructions):
        for kind, item, n in instructions:
            if kind == 'turn_right':
                self.turn_right()
            elif kind == 'turn_left':
                self.turn_left()
            elif kind == 'walk_forward':
                self.walk_forward(n)
        return (self.x, self.y)

