class Robot:
    def __init__(self):
        self.direction = 0  # 0: north, 1: east, 2: south, 3: west
        self.position = (0, 0)

    def turn_left(self):
        self.direction = (self.direction + 1) % 4

    def turn_right(self):
        self.direction = (self.direction - 1) % 4

    def walk(self, steps):
        if self.direction == 0:
            self.position = (self.position[0], self.position[0] + steps)
        elif self.direction == 1:
            self.position = (self.position[1], self.position[1] + steps)
        elif self.direction == 2:
            self.position = (self.position[0], self.position[0] - steps)
        elif self.direction == 3:
            self.position = (self.position[1], self.position[1] - steps)

def main():
    robot = Robot()
