class Robot:
    def __init__(self, start_position=(0, 0), facing='north'):
        self.position = start_position
        self.facing = facing

    def turn_right(self):
        if self.facing == 'north':
            self.facing = 'east'
        elif self.facing == 'east':
            self.facing = 'south'
        elif self.facing == 'south':
            self.facing = 'west'
        elif self.facing == 'west':
            self.facing = 'north'

