from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def turn(self, direction):
        if direction == 'right':
            self.y += 1
        elif direction == 'left':
            self.y -= 1
        elif direction == 'forward':
            self.x += 1
        else:
            raise ValueError("Invalid direction: {}".format(direction))

    def move(self, steps):
        for _ in range(steps):
            self.turn('forward')

    def move_north(self, steps):
        for _ in range(steps):
            self.turn('right')

    def move_east(self, steps):
        for _ in range(steps):
            self.turn('left')

    def move_backward(self, steps):
        for _ in range(steps):
            self.turn('forward')

    def turn_right(self):
        self.turn('right')

    def turn_left(self):
        self.turn('left')

    def turn_north(self):
        self.turn('right')

    def turn_east(self):
        self.turn('left')

    def turn_south(self):
        self.turn('left')

    def turn_west(self):
        self.turn('right')

