class Robot:
    def __init__(self):
        self.direction = 'n'  # Initially facing north

    def turn_left(self):
        if self.direction == 'n':  # Turn right
            self.direction = 'w'
        elif self.direction == 'w':  # Turn left
            self.direction = 's'
        elif self.direction == 's':  # Turn right
            self.direction = 'e'
        elif self.direction == 'e':  # Turn left
            self.direction = 'n'

    def turn_right(self):
        if self.direction == 'n':  # Turn right
            self.direction = 'e'
        elif self.direction == 'e':  # Turn left
            self.direction = 's'
        elif self.direction == 's':  # Turn right
            self.direction = 'w'
        elif self.direction == 'w':  # Turn left
            self.direction = 'n'

    def move_forward(self, steps):
        if self.direction == 'n':
            for _ in range(steps):
                yield 0, 1
        elif self.direction == 's':
            for _ in range(steps):
                yield 0, -1
        elif self.direction == 'e':
            for _ in range(steps):
                yield 1, 0
        elif self.direction == 'w':
            for _ in range(steps):
                yield -1, 0

    def walk(self, steps):
        for _ in range(steps):
            yield from self.move_forward(steps)

    def turn_around(self):
        if self.direction == 'n':
            self.direction = 's'
        elif self.direction == 's':
            self.direction = 'n'
        elif self.direction == 'e':
            self.direction = 'w'
        elif self.direction == 'w':
            self.direction = 'e'

    def move(self, steps):
        for _ in range(steps):
            yield from self.walk(steps)

    def __repr__(self):
        return f'Robot at {self.position()} facing {self.direction}'

def main():
    robot = Robot()
    for _ in range(8):
        robot.turn_right()
    robot.turn_right()
    robot.turn_right()
    robot.turn_right()
    robot.turn_right()
    robot.turn_left()
    robot.turn_left()
    robot.turn_left()
    for _ in range(2):
        robot.turn_around()
    robot.move(2)
    return robot

if __name__ == '__main__':
    print(main())
