class Robot:
    def __init__(self, start=(0, 0), facing="north"):
        self.position = start
        self.facing = facing

    def turn_left(self):
        if self.facing == "north":
            self.facing = "west"
        elif self.facing == "west":
            self.facing = "south"
        elif self.facing == "south":
            self.facing = "east"
        elif self.facing == "east":
            self.facing = "north"

    def walk(self, steps):
        if self.facing == "north":
            self.position = (self.position[0], self.position[1] + steps)
        elif self.facing == "west":
            self.position = (self.position[0] - steps, self.position[1])
        elif self.facing == "south":
            self.position = (self.position[0], self.position[1] - steps)
        elif self.facing == "east":
            self.position = (self.position[0] + steps, self.position[1])

    def turn_right(self):
        if self.facing == "north":
            self.facing = "east"
        elif self.facing == "east":
            self.facing = "south"
        elif self.facing == "south":
            self.facing = "west"
        elif self.facing == "west":
            self.facing = "north"

    def move(self):
        if self.facing == "north":
            self.position = (self.position[0], self.position[1] + 1)
        elif self.facing == "west":
            self.position = (self.position[0] - 1, self.position[1])
        elif self.facing == "south":
            self.position = (self.position[0], self.position[1] - 1)
        elif self.facing == "east":
            self.position = (self.position[0] + 1, self.position[1])

