from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.directions = deque([0, 1, 0, -1])

    def turn_right(self):
        self.directions.rotate(-1)

    def turn_left(self):
        self.directions.rotate(1)

    def move_forward(self, n):
        for _ in range(n):
            if self.directions[-1] == 0:  # north
                self.y += 1
            elif self.directions[-1] == 1:  # east
                self.x += 1
            elif self.directions[-1] == 2:  # south
                self.y -= 1
            elif self.directions[-1] == 3:  # west
                self.x -= 1

    def execute_instructions(self, instructions):
        for instruction in instructions:
            if instruction == 'right':
                self.turn_right()
            elif instruction == 'left':
                self.turn_left()
            elif instruction == 'forward':
                self.move_forward(1)
            elif instruction == 'walk':
                self.move_forward(3)

    def final_position(self):
        return (self.x, self.y)

# Create robot and execute instructions
robot = Robot()
instructions = ['right', 'forward', 'forward', 'forward', 'left', 'left', 'right', 'left', 'forward', 'left', 'forward']
