from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.directions = deque([0, 1, 0, -1])

    def turn(self, instruction):
        if instruction == 'left':
            self.directions.rotate(-1)
        elif instruction == 'right':
            self.directions.rotate(1)
        else:
            self.directions.rotate(-2)

    def walk(self, steps):
        for _ in range(steps):
            self.y += self.directions.popleft()

def simulate(instructions):
    robot = Robot()
    for instruction in instructions:
        robot.turn(instruction)
        robot.walk(2)
    return robot.x, robot.y

