        if direction == 'N':
            self.y += steps
        elif direction == 'E':
            self.x += steps

    def turn(self, direction):
        if direction == 'L':
            if self.direction == 'N':
                self.direction = 'W'
            elif self.direction == 'W':
                self.direction = 'S'
            elif self.direction == 'S':
                self.direction = 'E'
        elif direction == 'R':
            if self.direction == 'N':
                self.direction = 'E'
            elif self.direction == 'W':
                self.direction = 'S'
            elif self.direction == 'S':
                self.direction = 'W'

    def walk(self, steps, direction):
        for _ in range(steps):
            if direction == 'N':
                self.move(1, 'N')
            elif direction == 'E':
                self.move(1, 'E')

    def final_position(self):
        return (self.x, self.y)

