        direction, action, steps = instruction

        if direction == 'turn':
            if action == 'left':
                facing_direction = (facing_direction - 1) % 4
            elif action == 'right':
                facing_direction = (facing_direction + 1) % 4
        elif direction == 'walk':
            if action == 'forward':
                if facing_direction == 0:
                    current_position[1] += steps
                elif facing_direction == 1:
                    current_position[0] += steps
                elif facing_direction == 2:
                    current_position[1] -= steps
                elif facing_direction == 3:
