class Robot:
    def __init__(self):
        self.position = (0, 0)
        self.direction = 'north'

    def turn(self, direction):
        if direction == 'right':
            self.direction = 'east'
        elif direction == 'left':
            self.direction = 'west'
        elif direction == 'forward':
            self.direction = self.direction.capitalize()

    def walk(self, steps):
        if self.direction == 'north':
            self.position = (self.position[0], self.position[1] + steps)
        elif self.direction == 'east':
            self.position = (self.position[0] + steps, self.position[1])
        elif self.direction == 'west':
            self.position = (self.position[0] - steps, self.position[1])
        elif self.direction == 'south':
            self.position = (self.position[0], self.position[1] - steps)

    def execute_instructions(self, instructions):
        for instruction in instructions:
            if instruction == '1':
                self.walk(1)
            elif instruction == '2':
                self.turn('right')
            elif instruction == '3':
                self.walk(3)
            elif instruction == '4':
                self.turn('left')
            elif instruction == '5':
                self.walk(1)
            elif instruction == '6':
                self.walk(2)
            elif instruction == '7':
                self.walk(2)
            elif instruction == '8':
                self.turn('right')
            elif instruction == '9':
                self.walk(4)
            elif instruction == '10':
                self.walk(4)

    def get_final_position(self):
        return self.position

