class Robot:
    def __init__(self, start_position=(0, 0), facing_direction='north'):
        self.position = start_position
        self.facing_direction = facing_direction

    def turn(self, direction):
        if direction == 'north':
            self.facing_direction = 'north'
        elif direction == 'east':
            self.facing_direction = 'east'
        elif direction == 'south':
            self.facing_direction = 'south'
        elif direction == 'west':
            self.facing_direction = 'west'

    def move(self, distance):
        if self.facing_direction == 'north':
            self.position = (self.position[0], self.position[1] + distance)
        elif self.facing_direction == 'east':
            self.position = (self.position[0] + distance, self.position[1])
        elif self.facing_direction == 'south':
            self.position = (self.position[0], self.position[1] - distance)
        elif self.facing_direction == 'west':
            self.position = (self.position[0] - distance, self.position[1])

    def run(self, instructions):
        for instruction in instructions:
            action, direction, distance = instruction
            if action == 'move':
                self.move(distance)
            elif action == 'turn':
                self.turn(direction)
        return self.position

