from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.directions = deque([0, 1, 0, -1])

    def turn_left(self):
        self.directions.rotate(-1)

    def turn_right(self):
        self.directions.rotate(1)

    def walk(self, steps):
        self.x += self.directions.popleft() * steps
        self.y += self.directions.popleft() * steps

    def run(self, instructions):
        for instruction in instructions:
            if instruction == "walk forward 1 step":
                self.walk(1)
            elif instruction == "turn left":
                self.turn_left()
            elif instruction == "turn right":
                self.turn_right()
            elif instruction == "turn around":
                self.turn_right()
                self.turn_right()
            elif instruction == "walk forward 2 steps":
                self.walk(2)
            elif instruction == "walk forward 4 steps":
                self.walk(4)
            elif instruction == "walk forward 1 step":
                self.walk(1)
            else:
                raise ValueError(f"Unknown instruction: {instruction}")

