    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    return directions[(directions.index((0, 1)) + 1) % 4]

def turn_left(direction):
    return turn_right(turn_right(direction))

def walk(steps, direction):
    dx, dy = direction
    return (dx * steps, dy * steps)

