class Robot:
    def __init__(self):
        self.x, self.y = 0, 0

    def turn(self, direction):
        # Turn left (n -> s), right (s -> n), and forward (n -> e), (s -> w)
        if direction == 'left':
            self.y, self.x = self.x, -self.y
        elif direction == 'right':
            self.y, self.x = self.x, self.y
        elif direction == 'forward':
            self.x, self.y = self.y, -self.x

    def walk(self, steps):
        self.x, self.y = self.x + steps * self.x, self.y + steps * self.y

    def run(self, instructions):
        for instruction, direction, steps in instructions:
            if instruction == 'turn':
                self.turn(direction)
            elif instruction == 'walk':
                self.walk(steps)

    def position(self):
        return (self.x, self.y)

# Create a robot and run the instructions
