        self.position = (0, 0)

    def turn_right(self):
        self.direction = (self.direction + 1) % 4

    def walk_forward(self, n):
        if self.direction == 0:
            self.position = (self.position[0], self.position[0] + n)
        elif self.direction == 1:
            self.position = (self.position[1] + n, self.position[1])
        elif self.direction == 2:
            self.position = (self.position[0], self.position[0] - n)
        elif self.direction == 3:
            self.position = (self.position[1] - n, self.position[1])

    def simulate(self, instructions):
        for instruction in instructions:
            if instruction[0] == 'turn_right':
                self.turn_right()
            elif instruction[0] == 'walk_forward':
                self.walk_forward(instruction[1])

    def get_position(self):
        return self.position

