    for i in range(len(turns)):
        if turns[i] == 'right':
            if i < len(steps):
                pos[1] += steps[i]
            else:
                pos[1] += 1
        elif turns[i] == 'left':
            if i < len(steps):
                pos[1] -= steps[i]
            else:
                pos[1] -= 1
        elif turns[i] == 'forward':
            if i < len(steps):
                pos[0] += steps[i]
            else:
                pos[0] += 1
    return pos

